import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Test coverage","description":"How Strauss-RS is tested: 723 automated tests that cover 92% of its lines, with coverage by area, how the tests are organised, and how to run them or measure coverage.","frontmatter":{"title":"Test coverage","description":"How Strauss-RS is tested: 723 automated tests that cover 92% of its lines, with coverage by area, how the tests are organised, and how to run them or measure coverage."},"headers":[],"relativePath":"test-coverage.md","filePath":"test-coverage.md"}`),a={name:`test-coverage.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to “Test coverage”">​</a></h1><p>Strauss-RS rewrites other people&#39;s code, so most of its tests check exactly what comes out. This page details what is tested, how the tests are organised and how to run them yourself.</p><h2 id="what-is-tested" tabindex="-1">What is tested <a class="header-anchor" href="#what-is-tested" aria-label="Permalink to “What is tested”">​</a></h2><p>There are 723 automated tests, and all of them pass. 615 are unit tests inside the program. The other 108 run the built <code>strauss-rs</code> program on a copy of a small PHP project and check the files and messages it produces.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Area</th><th style="text-align:right;">Unit tests</th><th style="text-align:right;">Lines covered</th><th style="text-align:left;">What they check</th></tr></thead><tbody><tr><td style="text-align:left;">Editing (<code>edits</code>)</td><td style="text-align:right;">152</td><td style="text-align:right;">95%</td><td style="text-align:left;">Rewriting namespaces, <code>use</code> statements, strings, docblocks and your own files in <code>update_call_sites</code>.</td></tr><tr><td style="text-align:left;">Renaming (<code>rename</code>)</td><td style="text-align:right;">89</td><td style="text-align:right;">96%</td><td style="text-align:left;">Which symbols are renamed and to what, including exclusions, autoload kinds and already-prefixed names.</td></tr><tr><td style="text-align:left;">PHP analysis (<code>analyser</code>)</td><td style="text-align:right;">86</td><td style="text-align:right;">86%</td><td style="text-align:left;">Finding declarations and references in PHP source, with their exact positions.</td></tr><tr><td style="text-align:left;">Configuration (<code>config</code>)</td><td style="text-align:right;">78</td><td style="text-align:right;">97%</td><td style="text-align:left;">Reading <code>strauss.json</code> and <code>composer.json</code>, defaults, inferred prefixes and every error message.</td></tr><tr><td style="text-align:left;">Packages (<code>packages</code>)</td><td style="text-align:right;">57</td><td style="text-align:right;">96%</td><td style="text-align:left;">Reading <code>installed.json</code>, finding each package&#39;s files, <code>.gitattributes</code>, and platform packages.</td></tr><tr><td style="text-align:left;">Writing output (<code>output</code>)</td><td style="text-align:right;">53</td><td style="text-align:right;">91%</td><td style="text-align:left;">Copying, in-place changes, the autoloader, file headers and deleting the originals.</td></tr><tr><td style="text-align:left;">Symbol table (<code>symbols</code>)</td><td style="text-align:right;">50</td><td style="text-align:right;">98%</td><td style="text-align:left;">Collecting symbols from every file, built-in and preset constants, and running in parallel.</td></tr><tr><td style="text-align:left;">Command line (<code>cli</code>, <code>commands</code>)</td><td style="text-align:right;">33</td><td style="text-align:right;">88%</td><td style="text-align:left;">Options, error messages, <code>init</code>, <code>migrate</code> and <code>explain</code>.</td></tr><tr><td style="text-align:left;">Patterns and workers</td><td style="text-align:right;">17</td><td style="text-align:right;">98%</td><td style="text-align:left;">PHP-style regular expressions, and results not depending on the number of workers.</td></tr></tbody></table><p>Lines covered counts the lines of each area&#39;s code that run in any test, unit or program. The figures are from <code>cargo llvm-cov</code> and include the program tests, so an area can be covered by tests that are not listed against it. The command line and commands share a row because they are tested together; the tiny <code>main.rs</code> is at 100% and left out of the table.</p><p>The 108 program tests are in seven files: <code>prefix</code> (23), <code>commands</code> (25), <code>packages</code> (17), <code>cli</code> (13), <code>rename</code> (11), <code>edits</code> (10) and <code>symbols</code> (9).</p><h2 id="overall" tabindex="-1">Overall <a class="header-anchor" href="#overall" aria-label="Permalink to “Overall”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Measure</th><th style="text-align:right;">Covered</th></tr></thead><tbody><tr><td style="text-align:left;">Lines</td><td style="text-align:right;">92.4%</td></tr><tr><td style="text-align:left;">Functions</td><td style="text-align:right;">93.3%</td></tr><tr><td style="text-align:left;">Regions</td><td style="text-align:right;">91.1%</td></tr></tbody></table><p>That is 6,519 of 7,057 lines. Branch coverage is not reported.</p><h2 id="kinds-of-test" tabindex="-1">Kinds of test <a class="header-anchor" href="#kinds-of-test" aria-label="Permalink to “Kinds of test”">​</a></h2><ul><li><strong>Small cases.</strong> Most unit tests give one piece of PHP to the analyser or editor and check the result, such as a <code>use</code> statement with an alias, a name inside a heredoc or a class named in an attribute.</li><li><strong>Whole-project fixtures.</strong> Folders under <code>test/</code> hold small projects with packages that exercise each rule. The tests copy a fixture to a scratch folder, run the pipeline or the program, and check the files that come out.</li><li><strong>Projects built by the test.</strong> Where a fixture would hide the point, the test writes its project itself. For example, the in-place tests prefix a project, restore one package&#39;s files as <code>composer update</code> would, prefix again, and check that the reinstalled package is prefixed and the untouched one is not prefixed twice.</li></ul><h2 id="run-them" tabindex="-1">Run them <a class="header-anchor" href="#run-them" aria-label="Permalink to “Run them”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>To run one area, give part of a test&#39;s name:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prefix</span></span></code></pre></div><h2 id="reproducing-coverage-results" tabindex="-1">Reproducing coverage results <a class="header-anchor" href="#reproducing-coverage-results" aria-label="Permalink to “Reproducing coverage results”">​</a></h2><p>Test coverage results provided by <a href="https://github.com/taiki-e/cargo-llvm-cov" target="_blank" rel="noreferrer">cargo-llvm-cov</a>:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cargo-llvm-cov</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llvm-cov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --html</span></span></code></pre></div><p>The report is written to <code>target/llvm-cov/html/index.html</code>. For a summary in the terminal, run <code>cargo llvm-cov</code> on its own.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};